const raw = $('WH Verificar Disponibilidad').first().json.body || $('WH Verificar Disponibilidad').first().json;
let args;
if (raw.arguments !== undefined) {
  args = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
} else {
  args = raw;
}
const servicio = String(args.servicio || '').trim();
const fecha = String(args.fecha || '').trim();
const hora = String(args.hora || '').trim();
const DURACIONES = {'Revision':30,'Limpieza dental':45,'Empaste':45,'Extraccion':30,'Blanqueamiento dental':60,'Consulta ortodoncia':30,'Consulta implantes':30,'Endodoncia':60};
const duracion = DURACIONES[servicio] || 30;
const [hh, mm] = hora.split(':').map(Number);
const totalFin = hh * 60 + mm + duracion;
const hFin = Math.floor(totalFin / 60) % 24;
const mFin = totalFin % 60;
const offset = '+02:00';
const d = new Date(`${fecha}T12:00:00Z`);
const diasSemana = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
return [{ json: { servicio, fecha, hora, duracion, fechaInicio: `${fecha}T${hora}:00${offset}`, fechaFin: `${fecha}T${String(hFin).padStart(2,'0')}:${String(mFin).padStart(2,'0')}:00${offset}`, fechaTexto: `${diasSemana[d.getUTCDay()]} ${d.getUTCDate()} de ${meses[d.getUTCMonth()]}` }}];

const input = $('Parsear Disponibilidad').first().json;
const eventos = $('GCal Consultar Hueco').all();
const newStart = new Date(input.fechaInicio);
const newEnd = new Date(input.fechaFin);
const eventosActivos = eventos.map(e => e.json).filter(e => e.status !== 'cancelled' && (e.start?.dateTime || e.start?.date));
const hayConflicto = eventosActivos.some(ev => {
  const evStart = new Date(ev.start.dateTime || ev.start.date + 'T00:00:00Z');
  const evEnd = new Date(ev.end.dateTime || ev.end.date + 'T00:00:00Z');
  return newStart < evEnd && newEnd > evStart;
});
if (!hayConflicto) {
  return [{ json: { disponible: true, fecha: input.fecha, hora: input.hora, servicio: input.servicio, mensaje: `Hay disponibilidad el ${input.fechaTexto} a las ${input.hora}` } }];
}
const [hh, mm] = input.hora.split(':').map(Number);
const totalSig = hh * 60 + mm + 60;
const hSig = Math.floor(totalSig / 60) % 24;
const mSig = totalSig % 60;
const sigHora = `${String(hSig).padStart(2,'0')}:${String(mSig).padStart(2,'0')}`;
const d = new Date(`${input.fecha}T12:00:00Z`);
const diasSemana = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const sigTexto = `${diasSemana[d.getUTCDay()]} ${d.getUTCDate()} de ${meses[d.getUTCMonth()]}`;
return [{ json: { disponible: false, mensaje: `No hay disponibilidad a esa hora. El siguiente hueco libre es el ${sigTexto} a las ${sigHora}`, siguiente_disponible: { fecha: input.fecha, hora: sigHora } } }];

const raw = $('WH Crear Cita').first().json.body || $('WH Crear Cita').first().json;
let body;
if (raw.arguments !== undefined) {
  body = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
} else {
  body = raw;
}
const nombre = String(body.nombre || '').trim();
const telefono = String(body.telefono || '').trim();
const servicio = String(body.servicio || '').trim();
const fecha = String(body.fecha || '').trim();
const hora = String(body.hora || '').trim();
const notas = String(body.notas || '').trim();
const DURACIONES = {'Revision':30,'Limpieza dental':45,'Empaste':45,'Extraccion':30,'Blanqueamiento dental':60,'Consulta ortodoncia':30,'Consulta implantes':30,'Endodoncia':60};
const duracion = DURACIONES[servicio] || 30;
const [hh, mm] = hora.split(':').map(Number);
const totalFin = hh * 60 + mm + duracion;
const hFin = Math.floor(totalFin / 60) % 24;
const mFin = totalFin % 60;
const offset = '+02:00';
const fechaInicio = `${fecha}T${hora}:00${offset}`;
const fechaFin = `${fecha}T${String(hFin).padStart(2,'0')}:${String(mFin).padStart(2,'0')}:00${offset}`;
const d = new Date(`${fecha}T12:00:00Z`);
const diasSemana = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const diaSemana = diasSemana[d.getUTCDay()];
const diaMes = d.getUTCDate();
const mes = meses[d.getUTCMonth()];
const descripcion = `Paciente: ${nombre}\nTeléfono: ${telefono}\nServicio: ${servicio}\nDuración: ${duracion} min${notas ? '\nNotas: ' + notas : ''}\nCreado por: Recepcionista IA Sara`;
return [{ json: { nombre, telefono, servicio, fecha, hora, notas, duracion, fechaInicio, fechaFin, tituloEvento: `${nombre} - ${servicio}`, descripcion, diaSemana, diaMes, mes } }];

const gcal = $('GCal Crear Evento').first().json;
const datos = $('Parsear Crear Cita').first().json;
return [{ json: { ...datos, calendar_event_id: gcal.id || '' } }];

const datos = $('Añadir Calendar ID').first().json;
const gcal = $('GCal Crear Evento').first().json;
if (gcal.id) {
  return [{ json: { confirmado: true, id_cita: gcal.id, mensaje_confirmacion: `Cita confirmada. Te esperamos el ${datos.diaSemana} ${datos.diaMes} de ${datos.mes} a las ${datos.hora} para tu ${datos.servicio.toLowerCase()}. Recibirás la confirmación por WhatsApp.` } }];
}
return [{ json: { confirmado: false, error: 'calendar_error', mensaje: '¡Vaya! Ha habido un problema al crear la cita. ¿Quieres que lo intentemos de nuevo?' } }];

const raw = $('WH Cancelar Cita').first().json.body || $('WH Cancelar Cita').first().json;
let args;
if (raw.arguments !== undefined) {
  args = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
} else {
  args = raw;
}
return [{ json: { telefono: String(args.telefono || '').trim(), fecha: String(args.fecha || '').trim(), hora: String(args.hora || '').trim() } }];

const { telefono, fecha, hora } = $('Parsear Cancelar Cita').first().json;
const filas = $('Sheets Leer Cancelar').all();
const fila = filas.find(f => {
  const d = f.json;
  return String(d['Teléfono'] || '').trim() === telefono &&
         String(d['Fecha'] || '').trim() === fecha &&
         d['Estado'] === 'CONFIRMADA' &&
         (!hora || String(d['Hora'] || '').trim() === hora);
});
if (!fila) {
  return [{ json: { encontrado: false, calendarEventId: null, telefono, fecha, hora, mensaje: 'No encontré ninguna cita activa para ese teléfono y fecha.' } }];
}
const dd = new Date(`${fecha}T12:00:00Z`);
const diasSemana = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
return [{ json: { encontrado: true, calendarEventId: fila.json['Calendar_Event_ID'], nombre: fila.json['Nombre'], servicio: fila.json['Servicio'], telefono, fecha, hora: fila.json['Hora'], fechaTexto: `${diasSemana[dd.getUTCDay()]} ${dd.getUTCDate()} de ${meses[dd.getUTCMonth()]}` } }];

const datos = $('Buscar Cita Cancelar').first().json;
if (!datos.encontrado) {
  return [{ json: { cancelado: false, mensaje: datos.mensaje } }];
}
return [{ json: { cancelado: true, mensaje: `Tu cita del ${datos.fechaTexto} ha quedado cancelada. Cuando quieras volver, aquí estaremos.` } }];

const raw = $('WH Modificar Cita').first().json.body || $('WH Modificar Cita').first().json;
let args;
if (raw.arguments !== undefined) {
  args = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
} else {
  args = raw;
}
return [{ json: { telefono: String(args.telefono || '').trim(), fecha_actual: String(args.fecha_actual || '').trim(), hora_actual: String(args.hora_actual || '').trim(), nueva_fecha: String(args.nueva_fecha || '').trim(), nueva_hora: String(args.nueva_hora || '').trim() } }];

const { telefono, fecha_actual, hora_actual, nueva_fecha, nueva_hora } = $('Parsear Modificar Cita').first().json;
const filas = $('Sheets Leer Modificar').all();
const fila = filas.find(f => {
  const d = f.json;
  return String(d['Teléfono'] || '').trim() === telefono &&
         String(d['Fecha'] || '').trim() === fecha_actual &&
         d['Estado'] === 'CONFIRMADA' &&
         (!hora_actual || String(d['Hora'] || '').trim() === hora_actual);
});
if (!fila) {
  return [{ json: { encontrado: false, calendarEventId: null, nueva_fecha, nueva_hora } }];
}
const servicio = fila.json['Servicio'];
const DURACIONES = {'Revision':30,'Limpieza dental':45,'Empaste':45,'Extraccion':30,'Blanqueamiento dental':60,'Consulta ortodoncia':30,'Consulta implantes':30,'Endodoncia':60};
const duracion = DURACIONES[servicio] || 30;
const [hh, mm] = nueva_hora.split(':').map(Number);
const totalFin = hh * 60 + mm + duracion;
const hFin = Math.floor(totalFin / 60) % 24;
const mFin = totalFin % 60;
const offset = '+02:00';
const d = new Date(`${nueva_fecha}T12:00:00Z`);
const diasSemana = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
const meses = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
return [{ json: { encontrado: true, calendarEventId: fila.json['Calendar_Event_ID'], nombre: fila.json['Nombre'], servicio, telefono, fecha_actual, nueva_fecha, nueva_hora, nuevaFechaInicio: `${nueva_fecha}T${nueva_hora}:00${offset}`, nuevaFechaFin: `${nueva_fecha}T${String(hFin).padStart(2,'0')}:${String(mFin).padStart(2,'0')}:00${offset}`, fechaTexto: `${diasSemana[d.getUTCDay()]} ${d.getUTCDate()} de ${meses[d.getUTCMonth()]}` } }];

const datos = $('Buscar Cita Modificar').first().json;
if (!datos.encontrado) {
  return [{ json: { modificado: false, mensaje: 'No encontré ninguna cita activa para ese teléfono y fecha.' } }];
}
return [{ json: { modificado: true, mensaje: `Listo, tu cita ha quedado cambiada al ${datos.fechaTexto} a las ${datos.nueva_hora}.` } }];

const raw = $('WH Post Llamada').first().json.body || $('WH Post Llamada').first().json;
const event = raw.event || '';
if (event !== 'call_ended' && event !== 'call_analyzed') {
  return [{ json: { skip: true } }];
}
const analysis = raw.call_analysis || {};
const now = new Date().toISOString().replace('T',' ').substring(0,19);
return [{ json: { skip: false, ID: raw.call_id || '', Fecha_llamada: now, Duracion_seg: raw.duration_seconds || 0, Resumen: analysis.call_summary || '', Sentimiento: analysis.user_sentiment || 'Neutral', Exitosa: analysis.call_successful ? 'TRUE' : 'FALSE', Call_ID: raw.call_id || '' } }];
